<script setup>
import {createFirstEntryTracker} from '../lib/first-letter-entries.js';
import {ref,computed} from 'vue';
import {useI18n} from '../lib/i18n.js';
import {makeArrangement,placeToken,returnToken,arrangedBoxes,tileWrong,tileState} from '../lib/arrange-letters.js';
import {boxAnswer,boxesComplete,answerDirection} from '../lib/letter-boxes.js';
import LetterBoxes from './LetterBoxes.vue';
const props=defineProps({expected:String,disabled:Boolean,liveFeedback:Boolean,direction:String,modelValue:String,commitKey:String,letterLayout:Array,forceText:Boolean,dismissOnExact:Boolean,revealAnswer:Boolean});
const emit=defineEmits(['update:modelValue','committed-error','committed-answer']);const {t}=useI18n();
const tracker=createFirstEntryTracker();
const fallbackEditor=ref(null);
function cancelInput(){fallbackEditor.value?.cancelInput();}
defineExpose({cancelInput});
const initial=makeArrangement(props.expected);
const state=ref(!props.forceText&&initial&&initial.tokens.length>0&&initial.slots.length<=240?initial:null);const boxes=computed(()=>state.value?arrangedBoxes(state.value):[]);
const displayedBoxes=computed(()=>props.revealAnswer?boxes.value.map(box=>({...box,value:box.text})):boxes.value);
const used=computed(()=>new Set(state.value?.slots.map(slot=>slot.token)));
function update(next){if(props.disabled||props.revealAnswer)return;state.value=next;tracker.record(boxes.value,{strict:true});if(props.liveFeedback&&boxes.value.some(tileWrong))emit('committed-error',{key:props.commitKey});const value=boxesComplete(boxes.value)?boxAnswer(boxes.value):'';emit('update:modelValue',value);emit('committed-answer',{answer:value,key:props.commitKey,first_entries:tracker.entries(),input_mode:'slots'});}
</script>
<template><div v-if="state" class="arrangement" :class="{'revealed-answer':revealAnswer}"><span v-if="revealAnswer" class="reveal-announcement" role="status">{{expected}}</span><p v-if="revealAnswer" class="reveal-label">{{t('Skipped answer')}}</p><p v-if="!revealAnswer" class="muted small">{{t('Tap letters to build your answer. Tap a placed letter to return it.')}}</p><div class="arrange-slots" :dir="answerDirection(expected,direction)"><template v-for="(box,index) in displayedBoxes" :key="index"><span v-if="box.fixed" class="arrange-cell fixed">{{box.text}}</span><button v-else type="button" :disabled="disabled||revealAnswer||box.token===null" :class="['arrange-cell',liveFeedback&&!revealAnswer?tileState(box):'']" :aria-label="t('Letter {number}: {letter}',{number:index+1,letter:box.value||t('blank')})+(liveFeedback&&!revealAnswer&&tileState(box)?': '+t(tileState(box)==='incorrect'?'Incorrect placement':'Correct placement'):'')" @click="update(returnToken(state,index))">{{box.value||' '}}<span v-if="liveFeedback&&!revealAnswer&&tileState(box)" class="placement-mark" aria-hidden="true">{{tileState(box)==='incorrect'?'×':'✓'}}</span></button></template></div><div v-if="!revealAnswer" class="arrange-bank" :dir="answerDirection(expected,direction)" :aria-label="t('Available letters')"><button v-for="token in state.tokens" :key="token.id" type="button" class="arrange-cell" :disabled="disabled||used.has(token.id)" :aria-label="t('Place letter {letter}',{letter:token.text})" @click="update(placeToken(state,token.id))">{{token.text}}</button></div></div><p v-if="!state&&!revealAnswer" class="muted small">{{t('Use a written answer for very long text or when letter tiles are unavailable.')}}</p><LetterBoxes v-if="!state" ref="fallbackEditor" :expected="expected" :model-value="modelValue" :disabled="disabled" :direction="direction" :live-feedback="liveFeedback" :force-text="true" :reveal-answer="revealAnswer" :dismiss-on-exact="dismissOnExact" :letter-layout="letterLayout" :commit-key="commitKey" @committed-answer="emit('committed-answer',$event)" @update:model-value="emit('update:modelValue',$event)" @committed-error="emit('committed-error',$event)"/></template>
<style scoped>
.arrange-slots,.arrange-bank{display:flex;flex-wrap:wrap;gap:.3rem;max-width:100%;unicode-bidi:isolate;margin:1rem 0}.arrange-bank{padding-top:1rem;border-top:1px solid var(--practice-border,#b6ddc8)}.arrange-cell{position:relative;flex:0 0 2.75rem;width:2.75rem;max-width:100%;box-sizing:border-box;min-width:0;min-height:44px;padding:.2rem;font-size:1.1rem;border:1px solid var(--practice-border,#b6ddc8);background:white;color:var(--practice-ink,#164b3c);border-radius:.5rem;overflow-wrap:anywhere}.arrange-cell.fixed{display:grid;place-items:center;white-space:pre-wrap;background:var(--practice-soft,#e9f7ef)}.arrange-cell:focus-visible{outline:3px solid var(--practice-focus,#17644d);outline-offset:2px}.arrange-bank .arrange-cell:disabled{opacity:.3}.arrange-cell.correct{border:2px solid var(--practice-accent,#17644d);background:var(--practice-soft,#e9f7ef)}.arrange-cell.incorrect{border:2px solid #a42f36;background:#fff0f1}.placement-mark{position:absolute;right:1px;bottom:0;font-size:.7rem;font-weight:bold}
.revealed-answer .arrange-cell{background:#fff4df;border:1px solid #a97d31;color:#684812;opacity:1}.reveal-label{color:#684812;font-weight:600}
.reveal-announcement{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
</style>
